for shift in [5,70,135]:
 ds=[(b.GetBeginAtomIdx(),b.GetEndAtomIdx(),np.linalg.norm(x[shift+b.GetBeginAtomIdx()]-x[shift+b.GetEndAtomIdx()])) for b in m.GetBonds()]
 print('ligand',shift,'bond range',min(a[2] for a in ds),max(a[2] for a in ds))
 for a,b,d in ds:
  if (m.GetAtomWithIdx(a).GetSymbol()=='H' or m.GetAtomWithIdx(b).GetSymbol()=='H') and not .95<d<1.2: print('badH',a,b,d)
  elif not (m.GetAtomWithIdx(a).GetSymbol()=='H' or m.GetAtomWithIdx(b).GetSymbol()=='H') and not 1.2<d<1.7: print('badheavy',a,b,d)
for i,j,k in [(0,2,70),(1,3,135)]:
 a=x[i]-x[j];b=x[k]-x[j];print('Au angle',np.degrees(np.arccos(np.dot(a,b)/(np.linalg.norm(a)*np.linalg.norm(b)))))
